CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, salt TEXT NOT NULL, hash TEXT NOT NULL, balance REAL NOT NULL DEFAULT 1000, created INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS rounds(type TEXT NOT NULL, issue TEXT NOT NULL, num INTEGER NOT NULL, PRIMARY KEY(type,issue));
CREATE TABLE IF NOT EXISTS bets(id INTEGER PRIMARY KEY AUTOINCREMENT, uid INTEGER NOT NULL, type TEXT NOT NULL, issue TEXT NOT NULL, choice TEXT NOT NULL, amount REAL NOT NULL, endms INTEGER NOT NULL, status INTEGER NOT NULL DEFAULT 0, payout REAL NOT NULL DEFAULT 0, notified INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS bets_uid ON bets(uid,status,notified);
